private Stream<MapResult> xmlXpathToMapResult(@Name("url") String url,
                                              boolean simpleMode,
                                              String path,
                                              Map<String, Object> config) throws Exception {
    if (config == null) {
        config = Collections.emptyMap();
    }
    boolean failOnError = (boolean) config.getOrDefault("failOnError", true);
    List<MapResult> result = new ArrayList<>();

    try {
        // Create a factory that is hardened against XXE attacks
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        factory.setNamespaceAware(true);
        factory.setIgnoringElementContentWhitespace(true);
        // Disable DOCTYPE declarations
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        // Prevent loading external DTDs
        factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
        factory.setFeature("http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);
        // Disable external entities
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        // Additional safety flags
        factory.setXIncludeAware(false);
        factory.setExpandEntityReferences(false);

        DocumentBuilder builder = factory.newDocumentBuilder();

        FileUtils.checkReadAllowed(url);
        @SuppressWarnings("unchecked")
        Map<String, Object> headers = (Map<String, Object>) config.getOrDefault("headers",
                                                                               Collections.emptyMap());

        Document doc = builder.parse(Util.openInputStream(url, headers, null));

        XPathFactory xPathFactory = XPathFactory.newInstance();
        XPath xPath = xPathFactory.newXPath();

        path = StringUtils.isEmpty(path) ? "/" : path;
        XPathExpression expr = xPath.compile(path);
        NodeList nodeList = (NodeList) expr.evaluate(doc, XPathConstants.NODESET);

        for (int i = 0; i < nodeList.getLength(); i++) {
            Deque<Map<String, Object>> stack = new LinkedList<>();
            handleNode(stack, nodeList.item(i), simpleMode);
            while (!stack.isEmpty()) {
                result.add(new MapResult(stack.pollFirst()));
            }
        }
    } catch (FileNotFoundException e) {
        if (!failOnError) {
            return Stream.of(new MapResult(Collections.emptyMap()));
        }
        throw new FileNotFoundException(e.getMessage());
    } catch (Exception e) {
        if (!failOnError) {
            return Stream.of(new MapResult(Collections.emptyMap()));
        }
        throw new Exception(e);
    }
    return result.stream();
}
