private static String normalizePath(final String path) {
    // Preserve null to allow callers to detect absence of a path
    if (path == null) {
        return null;
    }

    // If the path is empty, return the root path "/"
    if (path.isEmpty()) {
        return "/";
    }

    // Strip all leading '/' characters
    int i = 0;
    while (i < path.length() && path.charAt(i) == '/') {
        i++;
    }
    String stripped = path.substring(i);

    // Ensure a single leading '/' is present
    // If the original path was composed solely of slashes, stripped will be empty
    return "/" + stripped;
}
