     *         JSPWiki will figure out the page.
     */
    public String getForwardPage(HttpServletRequest request) {
        String pathInfo = request.getPathInfo();

        // If no path info is supplied, nothing to forward to.
        if (pathInfo == null || pathInfo.isEmpty()) {
            return null;
        }

        // Normalize path separators to a single '/' and remove any leading slashes.
        String normalized = pathInfo.replace('\\', '/');
        if (normalized.startsWith("/")) {
            normalized = normalized.substring(1);
        }

        // Reject any path containing directory traversal sequences or absolute paths.
        if (normalized.contains("..") || normalized.contains("//") || normalized.startsWith("/")) {
            return null;
        }

        // Only allow paths that match the whitelist of known JSP pages.
        if (!ALLOWED_PAGES.contains(normalized)) {
            return null;
        }

        return normalized;
    }

