import java.io.Closeable;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;

class RgbeInfo implements Closeable {

    private final InputStream in;

    // other methods

    /**
     * Decompresses data from {@code in} into {@code out}. The algorithm is a simple
     * run‑length encoding where a byte value > 128 indicates a repeat run and
     * otherwise indicates a literal copy. This implementation validates all
     * input and guards against malformed streams that could cause an infinite
     * loop or buffer overflow.
     *
     * @param in  the source stream containing compressed data
     * @param out the destination buffer that must be fully populated
     * @throws IOException if the stream ends prematurely or contains invalid data
     */
    private static void decompress(final InputStream in, final byte[] out) throws IOException {
        int position = 0;
        final int total = out.length;

        while (position < total) {
            int n = readByteOrThrow(in, "unexpected end of stream while reading control byte");

            if (n > 128) { // repeat run
                int value = readByteOrThrow(in, "unexpected end of stream while reading repeat value");
                int repeatCount = n & 0x7F; // lower 7 bits give the count

                if (position + repeatCount > total) {
                    throw new EOFException("compressed data specifies more bytes than output buffer allows");
                }

                byte v = (byte) value;
                for (int i = 0; i < repeatCount; i++) {
                    out[position++] = v;
                }
            } else { // literal run
                int literalCount = n;

                if (position + literalCount > total) {
                    throw new EOFException("compressed data specifies more bytes than output buffer allows");
                }

                for (int i = 0; i < literalCount; i++) {
                    int b = readByteOrThrow(in, "unexpected end of stream while reading literal byte");
                    out[position++] = (byte) b;
                }
            }
        }
    }

    /**
     * Reads a single byte from {@code in} and returns it as an unsigned int.
     *
     * @param in          the input stream
     * @param errorPrefix a prefix for the exception message if EOF is encountered
     * @return the byte value (0–255)
     * @throws IOException if the stream ends before a byte can be read
     */
    private static int readByteOrThrow(InputStream in, String errorPrefix) throws IOException {
        int b = in.read();
        if (b == -1) {
            throw new EOFException(errorPrefix);
        }
        return b;
    }

    // other methods

    @Override
    public void close() throws IOException {
        in.close();
    }
}
