/**
 * Cleans up action name from suspicious characters
 *
 * @param rawActionName action name extracted from URI
 * @return safe action name or an empty string if the name is invalid
 */
protected String cleanupActionName(final String rawActionName) {
    // Guard against null input
    if (rawActionName == null) {
        return "";
    }

    // Accept only fully matched names
    if (allowedActionNames.matcher(rawActionName).matches()) {
        return rawActionName;
    }

    // Log the rejection – use the pattern string to avoid accidental formatting
    if (LOG.isWarnEnabled()) {
        LOG.warn("Action/method [{}] does not match allowed action names pattern [{}], rejecting it.",
                 rawActionName, allowedActionNames.pattern());
    }

    // Reject invalid action names by returning an empty string (or a predefined safe default)
    return "";
}
