import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import org.apache.commons.compress.archivers.ArchiveEntry;

/**
 * Utility class for safely extracting archive entries into a target directory.
 */
public class Expander {

    // other methods

    /**
     * Safely expands all entries supplied by {@code supplier} into {@code targetDirectory}.
     *
     * @param supplier      provides the next readable archive entry
     * @param writer        writes the entry data to an {@link OutputStream}
     * @param targetDirectory the directory where entries should be extracted
     * @throws IOException if an I/O error occurs or a path‑traversal attempt is detected
     */
    private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
        // Resolve the canonical path of the target directory once
        final String targetDirCanonical = targetDirectory.getCanonicalPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            final String entryName = nextEntry.getName();

            // Basic sanity checks on the entry name
            if (!isValidEntryName(entryName)) {
                throw new IOException("Invalid entry name: " + entryName);
            }

            // Resolve the file that will receive the entry
            File f = new File(targetDirectory, entryName);

            // Canonicalise the resulting path and ensure it stays within the target directory
            final String fileCanonical = f.getCanonicalPath();
            if (!fileCanonical.startsWith(targetDirCanonical)) {
                throw new IOException("expanding " + entryName + " would create file outside of " + targetDirectory);
            }

            if (nextEntry.isDirectory()) {
                if (!f.isDirectory() && !f.mkdirs()) {
                    throw new IOException("failed to create directory " + f);
                }
            } else {
                // Ensure parent directories exist
                File parent = f.getParentFile();
                if (!parent.isDirectory() && !parent.mkdirs()) {
                    throw new IOException("failed to create directory " + parent);
                }

                // Write the entry data
                try (OutputStream o = Files.newOutputStream(f.toPath())) {
                    writer.writeEntryDataTo(nextEntry, o);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    /**
     * Validates an archive entry name to prevent path traversal.
     *
     * @param name the raw entry name from the archive
     * @return {@code true} if the name is safe, {@code false} otherwise
     */
    private boolean isValidEntryName(String name) {
        if (name == null || name.isEmpty()) {
            return false;
        }

        // Reject absolute paths
        Path p = Paths.get(name);
        if (p.isAbsolute()) {
            return false;
        }

        // Normalize and check for upward traversal components
        Path normalized = p.normalize();
        for (Path part : normalized) {
            if (part.toString().equals("..")) {
                return false;
            }
        }

        // Reject names containing null characters or backslashes (Windows style)
        if (name.contains("\0") || name.contains("\\")) {
            return false;
        }

        return true;
    }

    // other methods
}
```

