private int readStored(final byte[] buffer, final int offset, final int length) throws IOException {
    // Handle entries that use a data descriptor – the data is cached in lastStoredEntry
    if (current.hasDataDescriptor) {
        if (lastStoredEntry == null) {
            readStoredEntry(); // populate lastStoredEntry
        }
        return lastStoredEntry.read(buffer, offset, length);
    }

    final long csize = current.entry.getSize();

    // Size must be non‑negative for a STORED entry. If it is unknown or negative,
    // treat it as an error – the caller should not rely on a size that cannot be
    // determined. This prevents an attacker from crafting a ZIP entry with a
    // bogus size that causes the loop below to run forever.
    if (csize < 0) {
        throw new IOException("Invalid entry size for stored entry: " + current.entry.getName());
    }

    // If the entry declares zero bytes, signal EOF immediately.
    if (csize == 0) {
        return -1;
    }

    // Remaining bytes that should be read for this entry.
    long remaining = csize - current.bytesRead;
    if (remaining <= 0) {
        return -1; // already finished
    }

    // Guard against integer overflow when converting to int for buffer operations.
    if (remaining > Integer.MAX_VALUE) {
        remaining = Integer.MAX_VALUE;
    }

    // Refill the internal buffer if it is exhausted.
    if (buf.position() >= buf.limit()) {
        buf.position(0);
        int l = in.read(buf.array());
        if (l == -1) {
            // Unexpected EOF before the declared size was reached.
            throw new IOException("Unexpected end of stream while reading stored entry '"
                    + current.entry.getName() + "'");
        }
        buf.limit(l);
        count(l);
        current.bytesReadFromStream += l;

        // Detect a malformed archive where the stream provides more data than
        // the declared size. This protects against infinite loops caused by
        // maliciously crafted ZIP files.
        if (current.bytesReadFromStream > csize + 1024) { // allow small slack for padding
            throw new IOException("Stored entry '" + current.entry.getName()
                    + "' exceeds declared size (" + csize + " bytes)");
        }
    }

    // Determine how many bytes to copy from the buffer.
    int toRead = Math.min(buf.remaining(), length);
    if (toRead > remaining) {
        toRead = (int) remaining;
    }

    buf.get(buffer, offset, toRead);
    current.bytesRead += toRead;
    return toRead;
}
